// Editorial judgments are conditional on explicit catalogue evidence. A missing anchor removes its claim.
export type EditorialClaim = {
  kind: "structure" | "complement" | "overlap" | "tradeoff" | "gap" | "outcome" | "insight" | "approach";
  tracks: string[];
  text: string;
  titles?: string[];
  notes?: string[];
  channels?: string[];
  absent?: string;
  minResources?: number;
  minimumTrackCounts?: Record<string, number>;
};
type EditorialSpec = {
  curriculumType: "sequential" | "exploratory" | "hybrid";
  claims: EditorialClaim[];
  insight: EditorialClaim;
  approach: EditorialClaim;
  startTrack?: string;
  contextTracks?: string[];
};
function claim(kind: EditorialClaim["kind"], tracks: string[], text: string, evidence: Omit<Partial<EditorialClaim>, "kind" | "tracks" | "text"> = {}): EditorialClaim {
  return { kind, tracks, text, ...evidence };
}
function collection(curriculumType: EditorialSpec["curriculumType"], claims: EditorialClaim[], insight: EditorialClaim, approach: EditorialClaim, startTrack?: string, contextTracks?: string[]): EditorialSpec {
  return { curriculumType, claims, insight, approach, ...(startTrack ? { startTrack } : {}), ...(contextTracks ? { contextTracks } : {}) };
}

